```go
package config_test

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

// CommandResult captures CLI execution output
type CommandResult struct {
	ExitCode int
	Stdout   string
	Stderr   string
}

func runCommand(t *testing.T, args ...string) CommandResult {
	t.Helper()
	cmd := exec.Command("./config-cli", args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	exitCode := 0
	if exitErr, ok := err.(*exec.ExitError); ok {
		exitCode = exitErr.ExitCode()
	}

	return CommandResult{
		ExitCode: exitCode,
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
	}
}

func TestArgumentParsing(t *testing.T) {
	// Table-driven. Efficient. Comprehensive.
	tests := []struct {
		name         string
		args         []string
		wantExitCode int
		wantStderr   string
	}{
		{"valid init", []string{"init"}, 0, ""},
		{"valid get", []string{"get", "database.host"}, 0, ""},
		{"valid set", []string{"set", "port", "8080"}, 0, ""},
		{"missing get key", []string{"get"}, 2, "missing required argument"},
		{"missing set value", []string{"set", "key"}, 2, "missing required argument"},
		{"unknown command", []string{"unknown"}, 2, "unknown command"},
		{"invalid flag", []string{"--invalid"}, 2, "unknown flag"},
		{"conflicting flags", []string{"--quiet", "--verbose", "list"}, 2, "conflicting"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := runCommand(t, tt.args...)
			if result.ExitCode != tt.wantExitCode {
				t.Errorf("exit code = %d, want %d", result.ExitCode, tt.wantExitCode)
			}
			if tt.wantStderr != "" && !bytes.Contains([]byte(result.Stderr), []byte(tt.wantStderr)) {
				t.Errorf("stderr missing %q", tt.wantStderr)
			}
		})
	}
}

func TestExitCodes(t *testing.T) {
	// Exit codes. Critical for scripting. Must be precise.
	tmpDir := t.TempDir()
	validConfig := filepath.Join(tmpDir, "valid.yaml")
	os.WriteFile(validConfig, []byte("key: value\n"), 0644)

	tests := []struct {
		name     string
		args     []string
		wantCode int
	}{
		{"success", []string{"--config", validConfig, "get", "key"}, 0},
		{"runtime error", []string{"--config", "/nonexistent/path", "get", "key"}, 1},
		{"usage error", []string{"invalid-subcommand"}, 2},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := runCommand(t, tt.args...)
			if result.ExitCode != tt.wantCode {
				t.Errorf("got %d, want %d", result.ExitCode, tt.wantCode)
			}
		})
	}
}

func TestOutputStreams(t *testing.T) {
	// Stdout for data. Stderr for errors. Never mix. Important distinction.
	tmpDir := t.TempDir()
	cfg := filepath.Join(tmpDir, "config.yaml")
	os.WriteFile(cfg, []byte("host: localhost\n"), 0644)

	t.Run("data to stdout", func(t *testing.T) {
		result := runCommand(t, "--config", cfg, "get", "host")
		if result.Stdout == "" {
			t.Error("expected stdout output")
		}
		if result.Stderr != "" {
			t.Error("unexpected stderr output")
		}
	})

	t.Run("errors to stderr", func(t *testing.T) {
		result := runCommand(t, "--config", cfg, "get", "nonexistent")
		if result.Stderr == "" {
			t.Error("expected stderr output")
		}
	})
}

func TestFileOperations(t *testing.T) {
	// File system. Many variables. Permissions. Race conditions.
	t.Run("init creates file", func(t *testing.T) {
		tmpDir := t.TempDir()
		cfg := filepath.Join(tmpDir, "new.yaml")
		result := runCommand(t, "--config", cfg, "init")
		if result.ExitCode != 0 {
			t.Fatal("init failed")
		}
		if _, err := os.Stat(cfg); os.IsNotExist(err) {
			t.Error("config file not created")
		}
	})

	t.Run("permission denied", func(t *testing.T) {
		tmpDir := t.TempDir()
		os.Chmod(tmpDir, 0000)
		defer os.Chmod(tmpDir, 0755)

		cfg := filepath.Join(tmpDir, "config.yaml")
		result := runCommand(t, "--config", cfg, "init")
		if result.ExitCode != 1 {
			t.Error("expected failure on permission denied")
		}
	})
}

func TestEdgeCases(t *testing.T) {
	// Edge cases. Where bugs hide. Must flush them out.
	t.Run("invalid yaml", func(t *testing.T) {
		tmpDir := t.TempDir()
		cfg := filepath.Join(tmpDir, "bad.yaml")
		os.WriteFile(cfg, []byte("invalid: yaml: content:\n  broken"), 0644)

		result := runCommand(t, "--config", cfg, "validate")
		if result.ExitCode != 1 {
			t.Error("should fail on invalid YAML")
		}
	})

	t.Run("empty config", func(t *testing.T) {
		tmpDir := t.TempDir()
		cfg := filepath.Join(tmpDir, "empty.yaml")
		os.WriteFile(cfg, []byte(""), 0644)

		result := runCommand(t, "--config", cfg, "list")
		if result.ExitCode != 0 {
			t.Error("empty config should be valid")
		}
	})
}
